UPDATE product SET name=#{input.name},category_id=CAST(#{input.categoryId} AS UNSIGNED),brand_id=CAST(#{input.brandId} AS UNSIGNED),
  description=#{input.description},featured=#{input.featured},version=version+1,updated_at=UTC_TIMESTAMP(3)
WHERE id=CAST(#{id} AS UNSIGNED) AND version=#{version}
